package middleware

import (
	"net/http"
	"strings"
)

// SetHeader is a convenience handler to set a response header key/value
func SetHeader(key, value string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set(key, value)
			next.ServeHTTP(w, r)
		})
	}
}

// AllowContentType enforces a whitelist of request Content-Types otherwise responds
// with a 415 Unsupported Media Type status.
func AllowContentType(contentTypes ...string) func(http.Handler) http.Handler {
	allowedContentTypes := make(map[string]struct{}, len(contentTypes))
	for _, ctype := range contentTypes {
		allowedContentTypes[strings.TrimSpace(strings.ToLower(ctype))] = struct{}{}
	}

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if !hasRequestBody(r) {
				// Skip check for empty content body
				next.ServeHTTP(w, r)
				return
			}

			s, _, _ := strings.Cut(r.Header.Get("Content-Type"), ";")
			s = strings.ToLower(strings.TrimSpace(s))

			if _, ok := allowedContentTypes[s]; ok {
				next.ServeHTTP(w, r)
				return
			}

			w.WriteHeader(http.StatusUnsupportedMediaType)
		})
	}
}

// RequireContentType enforces that a Content-Type header is present on requests
// with a body. If the Content-Type header is missing or empty, it responds with
// a 415 Unsupported Media Type status.
//
// This is useful for APIs that require clients to specify the content type of
// their request body, ensuring proper parsing and validation.
func RequireContentType(next http.Handler) http.Handler {
	fn := func(w http.ResponseWriter, r *http.Request) {
		// Skip check for requests without a body
		if !hasRequestBody(r) {
			next.ServeHTTP(w, r)
			return
		}

		// Check if Content-Type header is present and non-empty
		contentType := r.Header.Get("Content-Type")
		if contentType == "" {
			w.WriteHeader(http.StatusUnsupportedMediaType)
			return
		}

		next.ServeHTTP(w, r)
	}
	return http.HandlerFunc(fn)
}

// RequireContentTypeWithAllowed enforces that a Content-Type header is present
// on requests with a body AND that it matches one of the allowed content types.
// This combines the functionality of RequireContentType and AllowContentType.
//
// If the Content-Type header is missing, empty, or not in the allowed list,
// it responds with a 415 Unsupported Media Type status.
func RequireContentTypeWithAllowed(contentTypes ...string) func(http.Handler) http.Handler {
	allowedContentTypes := make(map[string]struct{}, len(contentTypes))
	for _, ctype := range contentTypes {
		allowedContentTypes[strings.TrimSpace(strings.ToLower(ctype))] = struct{}{}
	}

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// Skip check for requests without a body
			if !hasRequestBody(r) {
				next.ServeHTTP(w, r)
				return
			}

			// Check if Content-Type header is present and non-empty
			contentType := r.Header.Get("Content-Type")
			if contentType == "" {
				w.WriteHeader(http.StatusUnsupportedMediaType)
				return
			}

			// Parse the content type (remove parameters like charset)
			s, _, _ := strings.Cut(contentType, ";")
			s = strings.ToLower(strings.TrimSpace(s))

			// Check if the content type is in the allowed list
			if _, ok := allowedContentTypes[s]; !ok {
				w.WriteHeader(http.StatusUnsupportedMediaType)
				return
			}

			next.ServeHTTP(w, r)
		})
	}
}

// hasRequestBody returns true if the request has a body (including chunked/unknown length).
func hasRequestBody(r *http.Request) bool {
	// ContentLength > 0 means known body length
	// ContentLength == -1 means unknown length (e.g., chunked encoding) - check if Body is present
	// ContentLength == 0 means no body
	if r.ContentLength > 0 {
		return true
	}
	if r.ContentLength == -1 {
		return r.Body != nil && r.Body != http.NoBody
	}
	return false
}

